package org.agentfrc.lesson;
import static org.junit.jupiter.api.Assertions.*;
import java.nio.file.*;import java.security.MessageDigest;import java.util.*;
import org.junit.jupiter.api.*;import edu.wpi.first.hal.HAL;import edu.wpi.first.wpilibj.simulation.*;
class CoupledDriveTest {
 static double inertia;static CoupledDriveRig.Parameters params;static Path out;static byte[] nativeProperties,assumptions;static Properties cad;
 static String sha(byte[] b)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b));}
 @BeforeAll static void setup()throws Exception{
  assertTrue(HAL.initialize(500,0));String step=System.getenv("FRC_CAD_STEP"),prop=System.getenv("FRC_CAD_PROPERTIES"),config=System.getenv("FRC_DRIVE_ASSUMPTIONS");assertNotNull(step);assertNotNull(prop);assertNotNull(config);assertNotNull(System.getenv("FRC_IO_OUTPUT"));out=Path.of(System.getenv("FRC_IO_OUTPUT"));nativeProperties=Files.readAllBytes(Path.of(prop));assumptions=Files.readAllBytes(Path.of(config));cad=new Properties();cad.load(new java.io.ByteArrayInputStream(nativeProperties));
  assertEquals("frc-wheel-io-fixture/v1",cad.getProperty("schema"));assertEquals("blocked",cad.getProperty("engineeringAcceptance"));assertEquals("nominal-bare-wheel-rotating-component-development-fixture",cad.getProperty("fixtureRole"));assertEquals(cad.getProperty("sourceSha256"),sha(Files.readAllBytes(Path.of(step))));inertia=Double.parseDouble(cad.getProperty("inertiaZKgM2"));
  Properties c=new Properties();c.load(new java.io.ByteArrayInputStream(assumptions));assertEquals(Set.of("schema","basis","massKg","yawInertiaKgM2","trackWidthM","tractionWheelRadiusM","motorToWheelReduction","openCircuitVolts","batteryResistanceOhm","chassisCadBinding","tractionContact","neutralMode","engineeringAcceptance"),c.stringPropertyNames());assertEquals("frc-coupled-drive-assumptions/v1",c.getProperty("schema"));assertEquals("hypothetical-unvalidated-chassis",c.getProperty("basis"));assertEquals("unavailable",c.getProperty("chassisCadBinding"));assertEquals("ideal-no-slip",c.getProperty("tractionContact"));assertEquals("short-circuit-dynamic-brake",c.getProperty("neutralMode"));assertEquals("blocked",c.getProperty("engineeringAcceptance"));
  params=new CoupledDriveRig.Parameters(Double.parseDouble(c.getProperty("massKg")),Double.parseDouble(c.getProperty("yawInertiaKgM2")),Double.parseDouble(c.getProperty("trackWidthM")),Double.parseDouble(c.getProperty("tractionWheelRadiusM")),Double.parseDouble(c.getProperty("motorToWheelReduction")),Double.parseDouble(c.getProperty("openCircuitVolts")),Double.parseDouble(c.getProperty("batteryResistanceOhm")));
 }
 @BeforeEach void enable(){DriverStationSim.resetData();DriverStationSim.setDsAttached(true);DriverStationSim.setEnabled(true);DriverStationSim.notifyNewData();}
 @AfterEach void disable(){DriverStationSim.setEnabled(false);DriverStationSim.notifyNewData();RoboRioSim.setVInVoltage(12);}
 @Test void handCalculatedSharedSupplyAndRejectedCharging(){
  assertThrows(IllegalArgumentException.class,()->new CoupledDriveRig.Parameters(1e-100,5,.6,.0762,10.71,12,.02));assertThrows(IllegalArgumentException.class,()->new CoupledDriveRig.Parameters(1,.01,2,.01,50,12,.02));
  assertThrows(IllegalArgumentException.class,()->new CoupledDriveRig.Parameters(Double.NaN,5,.6,.0762,10.71,12,.02));
  var x=SharedSupply.solve(12,.02,new double[]{.5,.5},new double[]{0,0},new double[]{.1,.1});assertEquals(12/1.1,x.volts(),1e-12);assertEquals(5*x.volts(),x.batteryAmps(),1e-10);assertTrue(x.maxElectricalResidualWatts()<1e-9);
  assertThrows(IllegalArgumentException.class,()->SharedSupply.solve(12,.02,new double[]{.5},new double[]{20},new double[]{.1}));assertThrows(IllegalArgumentException.class,()->SharedSupply.solve(12,.02,new double[]{Double.NaN},new double[]{0},new double[]{.1}));
 }
 @Test void zeroInputAndStraightSymmetry(){try(var rig=new CoupledDriveRig(params,inertia,1)){var z=rig.step(true,0,0,0,20);assertEquals(0,z.x(),1e-12);assertEquals(0,z.batteryAmps(),1e-12);for(int i=0;i<50;i++){var s=rig.step(true,2,2,0,20);assertEquals(s.leftSpeed(),s.rightSpeed(),1e-10);assertEquals(s.leftSpeed(),s.measuredLeft(),1e-8);assertEquals(0,s.heading(),1e-10);assertTrue(s.bus()<=params.voc());}assertEquals(0,rig.electricalLedgerResidual(),1e-7);}}
 @Test void differentialYawReturnsThroughRealGyro(){try(var rig=new CoupledDriveRig(params,inertia,1)){CoupledDriveRig.Sample s=null;for(int i=0;i<20;i++)s=rig.step(true,1,2,0,20);assertTrue(s.heading()>0);assertEquals(-Math.toDegrees(s.heading()),s.measuredHeading(),1e-8);}}
 @Test void corruptedLeftSensorIsNotCompensated(){try(var rig=new CoupledDriveRig(params,inertia,-1)){var s=rig.step(true,2,2,0,20);assertEquals(-s.leftSpeed(),s.measuredLeft(),1e-8);assertNotEquals(s.leftSpeed(),s.measuredLeft());}}
 @Test void disableIsZeroDemandButDynamicBrakeNotInstantStop(){try(var rig=new CoupledDriveRig(params,inertia,1)){CoupledDriveRig.Sample s=null;for(int i=0;i<10;i++)s=rig.step(true,2,2,0,20);var d=rig.step(false,2,2,0,20);assertEquals(0,d.leftDuty());assertEquals(0,d.rightDuty());assertEquals(0,d.auxDuty());assertEquals(0,d.batteryAmps(),1e-8);assertTrue(d.leftSpeed()>0&&d.leftSpeed()<s.leftSpeed());}}
 @Test void genuineAuxiliarySharesDriveSupply(){double alone,loaded;try(var rig=new CoupledDriveRig(params,inertia,1)){alone=rig.step(true,2,2,0,20).bus();}try(var rig=new CoupledDriveRig(params,inertia,1)){loaded=rig.step(true,2,2,.6,20).bus();}assertTrue(loaded<alone,"Auxiliary draw must affect the same drive bus");}
 @Test void undervoltageInhibitsAllDemands(){var p=new CoupledDriveRig.Parameters(45,5,.6,.0762,10.71,5,.02);try(var rig=new CoupledDriveRig(p,inertia,1)){var s=rig.step(true,3,3,1,20);assertEquals(0,s.leftDuty());assertEquals(0,s.rightDuty());assertEquals(0,s.auxDuty());assertEquals(5,s.bus());}}
 @Test void extendedTurnRejectsUnsupportedCharging(){var error=assertThrows(IllegalArgumentException.class,()->{try(var rig=new CoupledDriveRig(params,inertia,1)){for(int i=0;i<100;i++)rig.step(true,1,2,.6,20);}});assertEquals("Unsupported regeneration",error.getMessage());}
 @Test void openBranchIsNotShortCircuitOrCharging(){
  var mixed=SharedSupply.solve(12,.02,new double[]{.5,0,.25},new double[]{0,10,0},new double[]{.1,.2,.1},new boolean[]{true,false,true});double expectedV=12/1.0625;assertEquals(expectedV,mixed.volts(),1e-12);assertEquals(3.125*expectedV,mixed.batteryAmps(),1e-10);assertEquals(0,mixed.armatureAmps()[1]);assertEquals(12,mixed.volts()+.02*mixed.batteryAmps(),1e-12);assertTrue(mixed.maxElectricalResidualWatts()<1e-9);assertThrows(IllegalArgumentException.class,()->SharedSupply.solve(12,.02,new double[]{.5,0},new double[]{0,10},new double[]{.1,.2},new boolean[]{true}));
  var open=SharedSupply.solve(12,.02,new double[]{0},new double[]{10},new double[]{.1},new boolean[]{false});var brake=SharedSupply.solve(12,.02,new double[]{0},new double[]{10},new double[]{.1});assertEquals(0,open.armatureAmps()[0]);assertEquals(0,open.batteryAmps());assertEquals(-100,brake.armatureAmps()[0]);assertEquals(0,brake.batteryAmps());assertThrows(IllegalArgumentException.class,()->SharedSupply.solve(12,.02,new double[]{.1},new double[]{0},new double[]{.1},new boolean[]{false}));
 }
 @Test void mixedSideCoastUsesStageLocalZeroTorque(){
  var motor=edu.wpi.first.math.system.plant.DCMotor.getNEO(2);var model=new NeutralDrivetrainSim(motor,10.71,5,45,.0762,.6);model.setOpen(false,true);
  var state=edu.wpi.first.math.VecBuilder.fill(0,0,0,1,.5,0,0);var held=edu.wpi.first.math.VecBuilder.fill(3,0);var dx=model.getDynamics(state,held);
  double current=(3-1*10.71/.0762/motor.KvRadPerSecPerVolt)/motor.rOhms;double force=10.71*motor.KtNMPerAmp*current/.0762;
  assertEquals(force*(1.0/45+.3*.3/5),dx.get(3,0),1e-9);assertEquals(force*(1.0/45-.3*.3/5),dx.get(4,0),1e-9);assertEquals(0,held.get(1,0),0,"Stage cancellation must not mutate held input");assertThrows(UnsupportedOperationException.class,model::getCurrentDrawAmps);
 }
 @Test void brakeCoastComparisonKeepsMotionAndDissipationDistinct()throws Exception{
  StringBuilder trace=new StringBuilder("mode,tick,xM,leftMps,auxRadps,batteryA,copperDeltaJ,leftOpen,rightOpen,auxOpen\n");double[] travel=new double[2],loss=new double[2];int index=0;CoupledDriveRig.Sample initialState=null;
  for(var mode:CoupledDriveRig.NeutralMode.values()){
   try(var rig=new CoupledDriveRig(params,inertia,1,mode)){
    CoupledDriveRig.Sample before=null;for(int i=0;i<20;i++)before=rig.step(true,2,2,.6,20);if(initialState==null)initialState=before;else assertEquals(initialState,before,"Both neutral modes must share identical active-history terminal state");double initialCopper=rig.copperLossJ();CoupledDriveRig.Sample last=null;
    for(int i=0;i<50;i++){last=rig.step(false,2,2,.6,20);assertEquals(0,last.batteryAmps(),1e-8);if(mode==CoupledDriveRig.NeutralMode.COAST){assertEquals(before.leftSpeed(),last.leftSpeed(),1e-9);assertEquals(before.auxSpeed(),last.auxSpeed(),1e-9);assertTrue(last.leftOpen()&&last.rightOpen()&&last.auxiliaryOpen());}else assertFalse(last.leftOpen()||last.rightOpen()||last.auxiliaryOpen());trace.append(mode).append(',').append(i).append(',').append(last.x()).append(',').append(last.leftSpeed()).append(',').append(last.auxSpeed()).append(',').append(last.batteryAmps()).append(',').append(rig.copperLossJ()-initialCopper).append(',').append(last.leftOpen()).append(',').append(last.rightOpen()).append(',').append(last.auxiliaryOpen()).append('\n');}
    travel[index]=last.x()-before.x();loss[index]=rig.copperLossJ()-initialCopper;assertTrue(travel[index]>0);if(mode==CoupledDriveRig.NeutralMode.BRAKE)assertTrue(last.leftSpeed()<before.leftSpeed()&&last.auxSpeed()<before.auxSpeed());index++;
   }
  }
  assertTrue(travel[1]>travel[0]);assertTrue(loss[0]>0);assertEquals(0,loss[1],1e-10);Files.writeString(out.resolve("neutral-comparison.csv"),trace.toString(),StandardOpenOption.CREATE_NEW);
 }
 static List<CoupledDriveRig.Sample> neutralTrajectory(CoupledDriveRig.NeutralMode mode,int substeps){List<CoupledDriveRig.Sample> list=new ArrayList<>();try(var rig=new CoupledDriveRig(params,inertia,1,mode)){for(int i=0;i<70;i++)list.add(rig.step(i<20,2,2,.6,substeps));assertEquals(0,rig.electricalLedgerResidual(),1e-6);}return list;}
 @Test void bothNeutralModesRetainWholeTrajectoryRefinement()throws Exception{
  double position=0,speed=0,voltage=0,current=0,auxiliary=0;
  for(var mode:CoupledDriveRig.NeutralMode.values()){var a=neutralTrajectory(mode,20);var b=neutralTrajectory(mode,40);for(int i=0;i<a.size();i++){position=Math.max(position,Math.abs(a.get(i).x()-b.get(i).x()));speed=Math.max(speed,Math.abs(a.get(i).leftSpeed()-b.get(i).leftSpeed()));voltage=Math.max(voltage,Math.abs(a.get(i).bus()-b.get(i).bus()));current=Math.max(current,Math.abs(a.get(i).batteryAmps()-b.get(i).batteryAmps()));auxiliary=Math.max(auxiliary,Math.abs(a.get(i).auxSpeed()-b.get(i).auxSpeed()));assertEquals(a.get(i).leftOpen(),b.get(i).leftOpen());}}
  assertTrue(position<.01&&speed<.02&&voltage<.1&&current<1&&auxiliary<1,"Neutral development refinement bounds");Properties result=new Properties();result.setProperty("positionDifferenceM",Double.toString(position));result.setProperty("speedDifferenceMps",Double.toString(speed));result.setProperty("voltageDifferenceV",Double.toString(voltage));result.setProperty("currentDifferenceA",Double.toString(current));result.setProperty("auxSpeedDifferenceRadps",Double.toString(auxiliary));result.setProperty("engineeringAcceptance","blocked");try(var stream=Files.newOutputStream(out.resolve("neutral-refinement.properties"),StandardOpenOption.CREATE_NEW)){result.store(stream,"Development quadrature/refinement, not physical validation");}
 }
 static List<CoupledDriveRig.Sample> trajectory(int substeps,double leftTarget){List<CoupledDriveRig.Sample> samples=new ArrayList<>();try(var rig=new CoupledDriveRig(params,inertia,1)){for(int i=0;i<(leftTarget==2?100:20);i++)samples.add(rig.step(true,leftTarget,2,.6,substeps));assertEquals(0,rig.electricalLedgerResidual(),1e-6);}return samples;}
 @Test void fullTrajectoryConvergenceAndExactInputClassBinding()throws Exception{
  var coarse=trajectory(20,2);var fine=trajectory(40,2);double maxPosition=0,maxSpeed=0,maxBus=0,maxAux=0,maxCurrent=0,maxHeading=0;StringBuilder csv=new StringBuilder("tick,xM,yM,headingRad,leftMps,rightMps,busV,batteryA,auxRadps\n");
  for(int i=0;i<coarse.size();i++){var a=coarse.get(i);var b=fine.get(i);maxPosition=Math.max(maxPosition,Math.abs(a.x()-b.x()));maxSpeed=Math.max(maxSpeed,Math.abs(a.leftSpeed()-b.leftSpeed()));maxBus=Math.max(maxBus,Math.abs(a.bus()-b.bus()));maxAux=Math.max(maxAux,Math.abs(a.auxSpeed()-b.auxSpeed()));maxCurrent=Math.max(maxCurrent,Math.abs(a.batteryAmps()-b.batteryAmps()));csv.append(i).append(',').append(a.x()).append(',').append(a.y()).append(',').append(a.heading()).append(',').append(a.leftSpeed()).append(',').append(a.rightSpeed()).append(',').append(a.bus()).append(',').append(a.batteryAmps()).append(',').append(a.auxSpeed()).append('\n');}
  var yawCoarse=trajectory(20,1);var yawFine=trajectory(40,1);
  for(int i=0;i<yawCoarse.size();i++){var a=yawCoarse.get(i);var b=yawFine.get(i);maxPosition=Math.max(maxPosition,Math.hypot(a.x()-b.x(),a.y()-b.y()));maxSpeed=Math.max(maxSpeed,Math.max(Math.abs(a.leftSpeed()-b.leftSpeed()),Math.abs(a.rightSpeed()-b.rightSpeed())));maxHeading=Math.max(maxHeading,Math.abs(a.heading()-b.heading()));maxBus=Math.max(maxBus,Math.abs(a.bus()-b.bus()));maxAux=Math.max(maxAux,Math.abs(a.auxSpeed()-b.auxSpeed()));maxCurrent=Math.max(maxCurrent,Math.abs(a.batteryAmps()-b.batteryAmps()));}
  assertTrue(maxAux<1,"development convergence auxiliary velocity");assertTrue(maxCurrent<1,"development convergence bus current");assertTrue(maxHeading<.01,"development convergence heading");
  assertTrue(maxPosition<.01,"development convergence position");assertTrue(maxSpeed<.02,"development convergence speed");assertTrue(maxBus<.1,"development convergence voltage");
  Files.writeString(out.resolve("io-trace.csv"),csv.toString(),StandardOpenOption.CREATE_NEW);Properties result=new Properties();result.setProperty("cadPropertiesSha256",sha(nativeProperties));result.setProperty("assumptionsSha256",sha(assumptions));result.setProperty("controllerClassSha256",sha(CoupledDriveController.class.getResourceAsStream("CoupledDriveController.class").readAllBytes()));result.setProperty("engineeringAcceptance","blocked");result.setProperty("maxPositionDifferenceM",Double.toString(maxPosition));result.setProperty("maxSpeedDifferenceMps",Double.toString(maxSpeed));result.setProperty("maxVoltageDifferenceV",Double.toString(maxBus));result.setProperty("maxAuxSpeedDifferenceRadps",Double.toString(maxAux));result.setProperty("maxCurrentDifferenceAmp",Double.toString(maxCurrent));result.setProperty("maxHeadingDifferenceRad",Double.toString(maxHeading));result.setProperty("chassisCadBinding","unavailable");try(var stream=Files.newOutputStream(out.resolve("io-result.properties"),StandardOpenOption.CREATE_NEW)){result.store(stream,"Executed hypothetical chassis coupling, not physical acceptance");}
 }
}
